select public.upsert_bank_question($json${"id":"hist-easy-001","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":6,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Quando os sacerdotes tocaram as trombetas e o povo gritou, o que aconteceu ao muro da cidade?","bible_ref":"Josué 6:20","verse_text":"Então o povo deu grito, e os sacerdotes tocaram as trombetas: e aconteceu que quando o povo ouviu o som da trombeta, deu o povo grito com grande barulho, e o muro caiu verticalmente. O povo subiu logo à cidade, cada um em frente de si, e tomaram-na."},"fr":{"prompt":"Quand les sacrificateurs sonnèrent des trompettes et que le peuple poussa des cris, qu’arriva-t-il à la muraille de la ville ?","bible_ref":"Josué 6:20","verse_text":"Le peuple poussa des cris, et les sacrificateurs sonnèrent des trompettes. Lorsque le peuple entendit le son de la trompette, il poussa de grands cris, et la muraille s’écroula; le peuple monta dans la ville, chacun devant soi. Ils s’emparèrent de la ville,"},"en":{"prompt":"When the priests blew the trumpets and the people shouted, what happened to the city wall?","bible_ref":"Joshua 6:20","verse_text":"So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."},"es":{"prompt":"Cuando los sacerdotes tocaron las trompetas y el pueblo gritó, ¿qué le pasó al muro de la ciudad?","bible_ref":"Josué 6:20","verse_text":"Entonces el pueblo dió grita, y los sacerdotes tocaron las bocinas: y aconteció que como el pueblo hubo oído el sonido de la bocina, dió el pueblo grita con gran vocerío, y el muro cayó á plomo. El pueblo subió luego á la ciudad, cada uno en derecho de sí, y tomáronla."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Caiu por terra"},"fr":{"text":"Elle s’écroula"},"en":{"text":"It fell down flat"},"es":{"text":"Cayó a plomo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ficou mais alto"},"fr":{"text":"Elle devint plus haute"},"en":{"text":"It grew taller"},"es":{"text":"Se hizo más alto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abriu-se uma porta"},"fr":{"text":"Une porte s’ouvrit"},"en":{"text":"A gate opened"},"es":{"text":"Se abrió una puerta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tremeu, mas ficou de pé"},"fr":{"text":"Elle trembla, mais resta debout"},"en":{"text":"It shook but stood"},"es":{"text":"Tembló, pero quedó en pie"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-002","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em casa de que mulher ficaram os dois espias que Josué enviou a Jericó?","bible_ref":"Josué 2:1","verse_text":"E Josué, filho de Num, enviou desde Sitim dois espias secretamente, dizendo-lhes: Andai, reconhecei a terra, e a Jericó. Os quais foram, e entraram em casa de uma mulher prostituta que se chamava Raabe, e passaram a noite ali."},"fr":{"prompt":"Dans la maison de quelle femme logèrent les deux espions envoyés par Josué à Jéricho ?","bible_ref":"Josué 2:1","verse_text":"Josué, fils de Nun, fit partir secrètement de Sittim deux espions, en leur disant: Allez, examinez le pays, et en particulier Jéricho. Ils partirent, et ils arrivèrent dans la maison d’une prostituée, qui se nommait Rahab, et ils y couchèrent."},"en":{"prompt":"In which woman’s house did the two spies sent by Joshua to Jericho stay?","bible_ref":"Joshua 2:1","verse_text":"And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there."},"es":{"prompt":"¿En casa de qué mujer se quedaron los dos espías que Josué envió a Jericó?","bible_ref":"Josué 2:1","verse_text":"Y JOSUÉ, hijo de Nun, envió desde Sittim dos espías secretamente, diciéndoles: Andad, reconoced la tierra, y á Jericó. Los cuales fueron, y entráronse en casa de una mujer ramera que se llamaba Rahab, y posaron allí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Raabe"},"fr":{"text":"Rahab"},"en":{"text":"Rahab"},"es":{"text":"Rahab"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rute"},"fr":{"text":"Ruth"},"en":{"text":"Ruth"},"es":{"text":"Ruth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Débora"},"fr":{"text":"Débora"},"en":{"text":"Deborah"},"es":{"text":"Débora"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dalila"},"fr":{"text":"Delila"},"en":{"text":"Delilah"},"es":{"text":"Dalila"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-003","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":4,"verse_start":4,"verse_end":5,"texts":{"pt":{"prompt":"Que profetisa julgava Israel sentada debaixo de uma palmeira?","bible_ref":"Juízes 4:4-5","verse_text":"E governava naquele tempo a Israel uma mulher, Débora, profetisa, mulher de Lapidote: A qual se sentava debaixo da palmeira de Débora entre Ramá e Betel, no monte de Efraim: e os filhos de Israel subiam a ela a juízo."},"fr":{"prompt":"Quelle prophétesse jugeait Israël, assise sous un palmier ?","bible_ref":"Juges 4:4-5","verse_text":"Dans ce temps-là, Débora, prophétesse, femme de Lappidoth, était juge en Israël. Elle siégeait sous le palmier de Débora, entre Rama et Béthel, dans la montagne d’Éphraïm; et les enfants d’Israël montaient vers elle pour être jugés."},"en":{"prompt":"Which prophetess judged Israel, sitting under a palm tree?","bible_ref":"Judges 4:4-5","verse_text":"And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time. And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment."},"es":{"prompt":"¿Qué profetisa juzgaba a Israel sentada debajo de una palmera?","bible_ref":"Jueces 4:4-5","verse_text":"Y gobernaba en aquel tiempo á Israel una mujer, Débora, profetisa, mujer de Lapidoth: La cual Débora habitaba debajo de una palma entre Rama y Beth-el, en el monte de Ephraim: y los hijos de Israel subían á ella á juicio."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Débora"},"fr":{"text":"Débora"},"en":{"text":"Deborah"},"es":{"text":"Débora"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ester"},"fr":{"text":"Esther"},"en":{"text":"Esther"},"es":{"text":"Esther"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rute"},"fr":{"text":"Ruth"},"en":{"text":"Ruth"},"es":{"text":"Ruth"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ana"},"fr":{"text":"Anne"},"en":{"text":"Hannah"},"es":{"text":"Anna"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-004","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":16,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Sansão disse que, se lhe rapassem a cabeça, perderia uma coisa. O quê?","bible_ref":"Juízes 16:17","verse_text":"Revelou-lhe, pois, todo seu coração, e disse-lhe: Nunca a minha cabeça chegou navalha; porque sou nazireu de Deus desde o ventre de minha mãe. Se for rapado, minha força se apartará de mim, e serei debilitado, e como todos os homens."},"fr":{"prompt":"Samson dit que, si on lui rasait la tête, il perdrait une chose. Laquelle ?","bible_ref":"Juges 16:17","verse_text":"il lui ouvrit tout son cœur, et lui dit: Le rasoir n’a point passé sur ma tête, parce que je suis consacré à Dieu dès le ventre de ma mère. Si j’étais rasé, ma force m’abandonnerait, je deviendrais faible, et je serais comme tout autre homme."},"en":{"prompt":"Samson said that if his head were shaved he would lose something. What?","bible_ref":"Judges 16:17","verse_text":"That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man."},"es":{"prompt":"Samsón dijo que, si le rapaban la cabeza, perdería algo. ¿Qué?","bible_ref":"Jueces 16:17","verse_text":"Descubrióle pues todo su corazón, y díjole: Nunca á mi cabeza llegó navaja; porque soy Nazareo de Dios desde el vientre de mi madre. Si fuere rapado, mi fuerza se apartará de mí, y seré debilitado, y como todos los hombres."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua força"},"fr":{"text":"Sa force"},"en":{"text":"His strength"},"es":{"text":"Su fuerza"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A sua vista"},"fr":{"text":"Sa vue"},"en":{"text":"His sight"},"es":{"text":"Su vista"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A sua voz"},"fr":{"text":"Sa voix"},"en":{"text":"His voice"},"es":{"text":"Su voz"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A sua coragem"},"fr":{"text":"Son courage"},"en":{"text":"His courage"},"es":{"text":"Su valor"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-005","type":"choice","level":"easy","testament":"ot","book":"RUT","chapter":1,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Quem disse: «O teu povo será o meu povo, e o teu Deus o meu Deus»?","bible_ref":"Rute 1:16","verse_text":"E Rute respondeu: Não me rogues que te deixe, e que me aparte de ti: porque de onde quer que tu fores, irei eu; e de onde quer que viveres, viverei. Teu povo será meu povo, e teu Deus meu Deus."},"fr":{"prompt":"Qui a dit : « Ton peuple sera mon peuple, et ton Dieu sera mon Dieu » ?","bible_ref":"Ruth 1:16","verse_text":"Ruth répondit: Ne me presse pas de te laisser, de retourner loin de toi! Où tu iras j’irai, où tu demeureras je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu;"},"en":{"prompt":"Who said, “Thy people shall be my people, and thy God my God”?","bible_ref":"Ruth 1:16","verse_text":"And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"},"es":{"prompt":"¿Quién dijo: «Tu pueblo será mi pueblo, y tu Dios mi Dios»?","bible_ref":"Rut 1:16","verse_text":"Y Ruth respondió: No me ruegues que te deje, y me aparte de ti: porque donde quiera que tú fueres, iré yo; y donde quiera que vivieres, viviré. Tu pueblo será mi pueblo, y tu Dios mi Dios."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Rute"},"fr":{"text":"Ruth"},"en":{"text":"Ruth"},"es":{"text":"Ruth"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Noemi"},"fr":{"text":"Naomi"},"en":{"text":"Naomi"},"es":{"text":"Noemi"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Orfa"},"fr":{"text":"Orpa"},"en":{"text":"Orpah"},"es":{"text":"Orpha"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ester"},"fr":{"text":"Esther"},"en":{"text":"Esther"},"es":{"text":"Esther"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-006","type":"choice","level":"easy","testament":"ot","book":"1SA","chapter":17,"verse_start":50,"verse_end":50,"texts":{"pt":{"prompt":"Com que venceu David o filisteu Golias?","bible_ref":"1 Samuel 17:50","verse_text":"Assim venceu Davi ao filisteu com funda e pedra; e feriu ao filisteu e o matou, sem ter Davi espada em sua mão."},"fr":{"prompt":"Avec quoi David a-t-il vaincu le Philistin Goliath ?","bible_ref":"1 Samuel 17:50","verse_text":"Ainsi, avec une fronde et une pierre, David fut plus fort que le Philistin; il le terrassa et lui ôta la vie, sans avoir d’épée à la main."},"en":{"prompt":"With what did David beat Goliath the Philistine?","bible_ref":"1 Samuel 17:50","verse_text":"So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."},"es":{"prompt":"¿Con qué venció David al filisteo Goliath?","bible_ref":"1 Samuel 17:50","verse_text":"Así venció David al Filisteo con honda y piedra; é hirió al Filisteo y matólo, sin tener David espada en su mano."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com uma funda e uma pedra"},"fr":{"text":"Avec une fronde et une pierre"},"en":{"text":"With a sling and a stone"},"es":{"text":"Con una honda y una piedra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com uma espada"},"fr":{"text":"Avec une épée"},"en":{"text":"With a sword"},"es":{"text":"Con una espada"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com um arco e flechas"},"fr":{"text":"Avec un arc et des flèches"},"en":{"text":"With a bow and arrows"},"es":{"text":"Con arco y flechas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com uma lança"},"fr":{"text":"Avec une lance"},"en":{"text":"With a spear"},"es":{"text":"Con una lanza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-007","type":"choice","level":"easy","testament":"ot","book":"2SA","chapter":6,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"O que fez David diante do SENHOR com toda a sua força?","bible_ref":"2 Samuel 6:14","verse_text":"E Davi saltava com toda sua força diante do SENHOR; e tinha vestido Davi um éfode de linho."},"fr":{"prompt":"Qu’a fait David devant l’Éternel de toute sa force ?","bible_ref":"2 Samuel 6:14","verse_text":"David dansait de toute sa force devant l’Éternel, et il était ceint d’un éphod de lin."},"en":{"prompt":"What did David do before the LORD with all his might?","bible_ref":"2 Samuel 6:14","verse_text":"And David danced before the LORD with all his might; and David was girded with a linen ephod."},"es":{"prompt":"¿Qué hizo David delante de Jehová con toda su fuerza?","bible_ref":"2 Samuel 6:14","verse_text":"Y David saltaba con toda su fuerza delante de Jehová; y tenía vestido David un ephod de lino."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Saltou"},"fr":{"text":"Il dansa"},"en":{"text":"He danced"},"es":{"text":"Saltó"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Chorou"},"fr":{"text":"Il pleura"},"en":{"text":"He wept"},"es":{"text":"Lloró"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dormiu"},"fr":{"text":"Il dormit"},"en":{"text":"He slept"},"es":{"text":"Durmió"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Escondeu-se"},"fr":{"text":"Il se cacha"},"en":{"text":"He hid"},"es":{"text":"Se escondió"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-008","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":3,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Em 1 Reis 3, o que pediu Salomão a Deus?","bible_ref":"1 Reis 3:9","verse_text":"Dá, pois, a teu servo um coração com entendimento para julgar ao teu povo, para discernir entre o bem e o mal; pois quem poderá governar este teu tão grande povo?"},"fr":{"prompt":"En 1 Rois 3, que demanda Salomon à Dieu ?","bible_ref":"1 Rois 3:9","verse_text":"Accorde donc à ton serviteur un cœur intelligent pour juger ton peuple, pour discerner le bien du mal! Car qui pourrait juger ton peuple, ce peuple si nombreux?"},"en":{"prompt":"In 1 Kings 3, what did Solomon ask God for?","bible_ref":"1 Kings 3:9","verse_text":"Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?"},"es":{"prompt":"En 1 Reyes 3, ¿qué le pidió Salomón a Dios?","bible_ref":"1 Reyes 3:9","verse_text":"Da pues á tu siervo corazón dócil para juzgar á tu pueblo, para discernir entre lo bueno y lo malo: porque ¿quién podrá gobernar este tu pueblo tan grande?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um coração entendido para julgar o povo"},"fr":{"text":"Un cœur intelligent pour juger le peuple"},"en":{"text":"An understanding heart to judge the people"},"es":{"text":"Un corazón dócil para juzgar al pueblo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Muitas riquezas"},"fr":{"text":"Beaucoup de richesses"},"en":{"text":"Great riches"},"es":{"text":"Muchas riquezas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma vida muito longa"},"fr":{"text":"Une très longue vie"},"en":{"text":"A very long life"},"es":{"text":"Una vida muy larga"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A morte dos seus inimigos"},"fr":{"text":"La mort de ses ennemis"},"en":{"text":"The death of his enemies"},"es":{"text":"La muerte de sus enemigos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-009","type":"choice","level":"easy","testament":"ot","book":"1KI","chapter":17,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Que aves traziam pão e carne ao profeta Elias junto ao ribeiro?","bible_ref":"1 Reis 17:6","verse_text":"E os corvos lhe traziam pão e carne pela manhã, e pão e carne à tarde; e bebia do ribeiro."},"fr":{"prompt":"Quels oiseaux apportaient du pain et de la viande au prophète Élie près du torrent ?","bible_ref":"1 Rois 17:6","verse_text":"Les corbeaux lui apportaient du pain et de la viande le matin, et du pain et de la viande le soir, et il buvait de l’eau du torrent."},"en":{"prompt":"Which birds brought bread and meat to the prophet Elijah by the brook?","bible_ref":"1 Kings 17:6","verse_text":"And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook."},"es":{"prompt":"¿Qué aves le traían pan y carne al profeta Elías junto al arroyo?","bible_ref":"1 Reyes 17:6","verse_text":"Y los cuervos le traían pan y carne por la mañana, y pan y carne á la tarde; y bebía del arroyo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Corvos"},"fr":{"text":"Des corbeaux"},"en":{"text":"Ravens"},"es":{"text":"Cuervos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pombas"},"fr":{"text":"Des colombes"},"en":{"text":"Doves"},"es":{"text":"Palomas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Águias"},"fr":{"text":"Des aigles"},"en":{"text":"Eagles"},"es":{"text":"Águilas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pardais"},"fr":{"text":"Des moineaux"},"en":{"text":"Sparrows"},"es":{"text":"Gorriones"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-010","type":"choice","level":"easy","testament":"ot","book":"2KI","chapter":5,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Em que rio mergulhou Naamã sete vezes para ficar curado?","bible_ref":"2 Reis 5:14","verse_text":"Ele então desceu, e mergulhou sete vezes no Jordão, conforme a palavra do homem de Deus; e sua carne se restaurou como a carne de um menino, e foi limpo."},"fr":{"prompt":"Dans quel fleuve Naaman s’est-il plongé sept fois pour être guéri ?","bible_ref":"2 Rois 5:14","verse_text":"Il descendit alors et se plongea sept fois dans le Jourdain, selon la parole de l’homme de Dieu; et sa chair redevint comme la chair d’un jeune enfant, et il fut pur."},"en":{"prompt":"In which river did Naaman dip himself seven times to be healed?","bible_ref":"2 Kings 5:14","verse_text":"Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."},"es":{"prompt":"¿En qué río se zambulló Naamán siete veces para quedar sano?","bible_ref":"2 Reyes 5:14","verse_text":"El entonces descendió, y zambullóse siete veces en el Jordán, conforme á la palabra del varón de Dios: y su carne se volvió como la carne de un niño, y fué limpio."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No Jordão"},"fr":{"text":"Dans le Jourdain"},"en":{"text":"The Jordan"},"es":{"text":"En el Jordán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No Nilo"},"fr":{"text":"Dans le Nil"},"en":{"text":"The Nile"},"es":{"text":"En el Nilo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No Eufrates"},"fr":{"text":"Dans l’Euphrate"},"en":{"text":"The Euphrates"},"es":{"text":"En el Eufrates"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No Tigre"},"fr":{"text":"Dans le Tigre"},"en":{"text":"The Tigris"},"es":{"text":"En el Tigris"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-011","type":"choice","level":"easy","testament":"ot","book":"EST","chapter":2,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Quem é que o rei fez rainha em lugar de Vasti?","bible_ref":"Ester 2:17","verse_text":"E o rei amou a Ester mais que todas as mulheres, e alcançou diante dele favor e benevolência mais que todas as virgens; e ele pôs a coroa real em sua cabeça, e a fez rainha em lugar de Vasti."},"fr":{"prompt":"Qui le roi fit-il reine à la place de Vasthi ?","bible_ref":"Esther 2:17","verse_text":"Le roi aima Esther plus que toutes les autres femmes, et elle obtint grâce et faveur devant lui plus que toutes les autres jeunes filles. Il mit la couronne royale sur sa tête, et la fit reine à la place de Vasthi."},"en":{"prompt":"Whom did the king make queen instead of Vashti?","bible_ref":"Esther 2:17","verse_text":"And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."},"es":{"prompt":"¿A quién hizo el rey reina en lugar de Vasthi?","bible_ref":"Ester 2:17","verse_text":"Y el rey amó á Esther sobre todas las mujeres, y halló gracia y benevolencia delante de él más que todas las vírgenes; y puso la corona real en su cabeza, é hízola reina en lugar de Vasthi."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ester"},"fr":{"text":"Esther"},"en":{"text":"Esther"},"es":{"text":"Esther"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rute"},"fr":{"text":"Ruth"},"en":{"text":"Ruth"},"es":{"text":"Ruth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mical"},"fr":{"text":"Mical"},"en":{"text":"Michal"},"es":{"text":"Michâl"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Débora"},"fr":{"text":"Débora"},"en":{"text":"Deborah"},"es":{"text":"Débora"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-easy-012","type":"choice","level":"easy","testament":"ot","book":"NEH","chapter":2,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"O que queria Neemias reconstruir em Jerusalém?","bible_ref":"Neemias 2:17","verse_text":"Então eu lhes disse: Com certeza vedes a miséria em que estamos, que Jerusalém está arruinada, e suas portas queimadas a fogo. Vinde, e reconstruamos o muro de Jerusalém, e não sejamos mais humilhados."},"fr":{"prompt":"Que voulait rebâtir Néhémie à Jérusalem ?","bible_ref":"Néhémie 2:17","verse_text":"Je leur dis alors: Vous voyez le malheureux état où nous sommes! Jérusalem est détruite, et ses portes sont consumées par le feu! Venez, rebâtissons la muraille de Jérusalem, et nous ne serons plus dans l’opprobre."},"en":{"prompt":"What did Nehemiah want to build up in Jerusalem?","bible_ref":"Nehemiah 2:17","verse_text":"Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach."},"es":{"prompt":"¿Qué quería reedificar Nehemías en Jerusalem?","bible_ref":"Nehemías 2:17","verse_text":"Díjeles pues: Vosotros veis el mal en que estamos, que Jerusalem está desierta, y sus puertas consumidas del fuego: venid, y edifiquemos el muro de Jerusalem, y no seamos más en oprobio."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O muro"},"fr":{"text":"La muraille"},"en":{"text":"The wall"},"es":{"text":"El muro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O palácio do rei"},"fr":{"text":"Le palais du roi"},"en":{"text":"The king’s palace"},"es":{"text":"El palacio del rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma torre muito alta"},"fr":{"text":"Une très haute tour"},"en":{"text":"A very high tower"},"es":{"text":"Una torre muy alta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O mercado"},"fr":{"text":"Le marché"},"en":{"text":"The market"},"es":{"text":"El mercado"}}}]}$json$::jsonb);
