select public.upsert_bank_question($json${"id":"hist-medium-001","type":"choice","level":"medium","testament":"ot","book":"JOS","chapter":2,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Que sinal disseram os espias que a mulher devia atar à janela?","bible_ref":"Josué 2:18","verse_text":"Eis que, quando nós entrarmos na terra, tu atarás este cordão de escarlate à janela pela qual nos fizeste descer: e tu juntarás em tua casa teu pai e tua mãe, teus irmãos e toda a família de teu pai."},"fr":{"prompt":"Quel signe les espions dirent-ils à la femme d’attacher à la fenêtre ?","bible_ref":"Josué 2:18","verse_text":"A notre entrée dans le pays, attache ce cordon de fil cramoisi à la fenêtre par laquelle tu nous fais descendre, et recueille auprès de toi dans la maison ton père, ta mère, tes frères, et toute la famille de ton père."},"en":{"prompt":"What sign did the spies tell the woman to bind in the window?","bible_ref":"Joshua 2:18","verse_text":"Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father’s household, home unto thee."},"es":{"prompt":"¿Qué señal dijeron los espías que la mujer debía atar a la ventana?","bible_ref":"Josué 2:18","verse_text":"He aquí, cuando nosotros entráremos en la tierra, tú atarás este cordón de grana á la ventana por la cual nos descolgaste: y tú juntarás en tu casa tu padre y tu madre, tus hermanos y toda la familia de tu padre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um cordão de fio escarlate"},"fr":{"text":"Un cordon de fil cramoisi"},"en":{"text":"A line of scarlet thread"},"es":{"text":"Un cordón de grana"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um pano branco"},"fr":{"text":"Un linge blanc"},"en":{"text":"A white cloth"},"es":{"text":"Un paño blanco"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um ramo de oliveira"},"fr":{"text":"Un rameau d’olivier"},"en":{"text":"An olive branch"},"es":{"text":"Un ramo de olivo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma lâmpada acesa"},"fr":{"text":"Une lampe allumée"},"en":{"text":"A burning lamp"},"es":{"text":"Una lámpara encendida"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-002","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":7,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Em Juízes 7, como beberam a água os trezentos homens escolhidos?","bible_ref":"Juízes 7:6","verse_text":"E foi o número dos que lamberam as águas, achegando-a com a mão à boca, trezentos homens: e todo aquele resto do povo se dobrou sobre seus joelhos para beber as águas."},"fr":{"prompt":"En Juges 7, comment les trois cents hommes choisis burent-ils l’eau ?","bible_ref":"Juges 7:6","verse_text":"Ceux qui lapèrent l’eau en la portant à la bouche avec leur main furent au nombre de trois cents hommes, et tout le reste du peuple se mit à genoux pour boire."},"en":{"prompt":"In Judges 7, how did the three hundred chosen men drink the water?","bible_ref":"Judges 7:6","verse_text":"And the number of them that lapped, putting their hand to their mouth, were three hundred men: but all the rest of the people bowed down upon their knees to drink water."},"es":{"prompt":"En Jueces 7, ¿cómo bebieron el agua los trescientos hombres escogidos?","bible_ref":"Jueces 7:6","verse_text":"Y fué el número de los que lamieron las aguas, llegándola con la mano á la boca, trescientos hombres: y todo el resto del pueblo se dobló sobre sus rodillas para beber las aguas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lamberam-na, levando a mão à boca"},"fr":{"text":"Ils lapèrent, portant la main à la bouche"},"en":{"text":"They lapped, putting their hand to their mouth"},"es":{"text":"La lamieron, llevando la mano a la boca"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De joelhos, com a boca na água"},"fr":{"text":"À genoux, la bouche dans l’eau"},"en":{"text":"On their knees, mouths in the water"},"es":{"text":"De rodillas, con la boca en el agua"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pelos seus capacetes"},"fr":{"text":"Dans leurs casques"},"en":{"text":"Out of their helmets"},"es":{"text":"En sus cascos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De cântaros de barro"},"fr":{"text":"Dans des cruches d’argile"},"en":{"text":"From clay pitchers"},"es":{"text":"De cántaros de barro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-003","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":14,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"O que havia dentro do corpo do leão morto quando Sansão voltou para o ver?","bible_ref":"Juízes 14:8","verse_text":"E voltando depois de alguns dias para tomá-la, apartou-se para ver o corpo morto do leão, e eis que no corpo do leão um enxame de abelhas, e um favo de mel."},"fr":{"prompt":"Qu’y avait-il dans le corps du lion mort quand Samson revint le voir ?","bible_ref":"Juges 14:8","verse_text":"Quelque temps après, il se rendit de nouveau à Thimna pour la prendre, et se détourna pour voir le cadavre du lion. Et voici, il y avait un essaim d’abeilles et du miel dans le corps du lion."},"en":{"prompt":"What was inside the dead lion’s carcase when Samson came back to see it?","bible_ref":"Judges 14:8","verse_text":"And after a time he returned to take her, and he turned aside to see the carcase of the lion: and, behold, there was a swarm of bees and honey in the carcase of the lion."},"es":{"prompt":"¿Qué había dentro del cuerpo del león muerto cuando Samsón volvió a verlo?","bible_ref":"Jueces 14:8","verse_text":"Y volviendo después de algunos días para tomarla, apartóse para ver el cuerpo muerto del león, y he aquí en el cuerpo del león un enjambre de abejas, y un panal de miel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um enxame de abelhas e mel"},"fr":{"text":"Un essaim d’abeilles et du miel"},"en":{"text":"A swarm of bees and honey"},"es":{"text":"Un enjambre de abejas y miel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um ninho de pássaros"},"fr":{"text":"Un nid d’oiseaux"},"en":{"text":"A bird’s nest"},"es":{"text":"Un nido de pájaros"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma serpente"},"fr":{"text":"Un serpent"},"en":{"text":"A serpent"},"es":{"text":"Una serpiente"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moedas de prata"},"fr":{"text":"Des pièces d’argent"},"en":{"text":"Pieces of silver"},"es":{"text":"Monedas de plata"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-004","type":"choice","level":"medium","testament":"ot","book":"RUT","chapter":1,"verse_start":3,"verse_end":4,"texts":{"pt":{"prompt":"Além de Rute, como se chamava a outra moabita que casou com um dos filhos de Noemi?","bible_ref":"Rute 1:3-4","verse_text":"E morreu Elimeleque, marido de Noemi, e restou ela com seus dois filhos; Os quais tomaram para si mulheres de Moabe, o nome da uma Orfa, e o nome da outra Rute; e habitaram ali uns dez anos."},"fr":{"prompt":"Outre Ruth, comment s’appelait l’autre Moabite qui épousa un des fils de Naomi ?","bible_ref":"Ruth 1:3-4","verse_text":"Élimélec, mari de Naomi, mourut, et elle resta avec ses deux fils. Ils prirent des femmes Moabites, dont l’une se nommait Orpa, et l’autre Ruth, et ils habitèrent là environ dix ans."},"en":{"prompt":"Besides Ruth, what was the name of the other woman of Moab who married one of Naomi’s sons?","bible_ref":"Ruth 1:3-4","verse_text":"And Elimelech Naomi’s husband died; and she was left, and her two sons. And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years."},"es":{"prompt":"Además de Ruth, ¿cómo se llamaba la otra moabita que se casó con uno de los hijos de Noemi?","bible_ref":"Rut 1:3-4","verse_text":"Y murió Elimelech, marido de Noemi, y quedó ella con sus dos hijos; Los cuales tomaron para sí mujeres de Moab, el nombre de la una Orpha, y el nombre de la otra Ruth; y habitaron allí unos diez años."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Orfa"},"fr":{"text":"Orpa"},"en":{"text":"Orpah"},"es":{"text":"Orpha"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mical"},"fr":{"text":"Mical"},"en":{"text":"Michal"},"es":{"text":"Michâl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abigail"},"fr":{"text":"Abigaïl"},"en":{"text":"Abigail"},"es":{"text":"Abigail"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Penina"},"fr":{"text":"Peninna"},"en":{"text":"Peninnah"},"es":{"text":"Peninna"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-005","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":1,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Porque deu Ana ao filho o nome de Samuel?","bible_ref":"1 Samuel 1:20","verse_text":"E sucedeu que, corrido o tempo, depois de Ana haver concebido, deu à luz um filho, e pôs-lhe o nome de Samuel, dizendo: “Pois eu o pedi ao SENHOR”."},"fr":{"prompt":"Pourquoi Anne donna-t-elle à son fils le nom de Samuel ?","bible_ref":"1 Samuel 1:20","verse_text":"Dans le cours de l’année, Anne devint enceinte, et elle enfanta un fils, qu’elle nomma Samuel, car, dit-elle, je l’ai demandé à l’Éternel."},"en":{"prompt":"Why did Hannah call her son Samuel?","bible_ref":"1 Samuel 1:20","verse_text":"Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."},"es":{"prompt":"¿Por qué le puso Anna a su hijo el nombre de Samuel?","bible_ref":"1 Samuel 1:20","verse_text":"Y fué que corrido el tiempo, después de haber concebido Anna, parió un hijo, y púsole por nombre Samuel, diciendo: Por cuanto lo demandé á Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Porque o tinha pedido ao SENHOR"},"fr":{"text":"Parce qu’elle l’avait demandé à l’Éternel"},"en":{"text":"Because she had asked him of the LORD"},"es":{"text":"Porque lo había pedido a Jehová"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Porque nasceu no templo"},"fr":{"text":"Parce qu’il était né dans le temple"},"en":{"text":"Because he was born in the temple"},"es":{"text":"Porque nació en el templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Porque era o nome do avô"},"fr":{"text":"Parce que c’était le nom de son grand-père"},"en":{"text":"Because it was his grandfather’s name"},"es":{"text":"Porque era el nombre de su abuelo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Porque um anjo lho mandou"},"fr":{"text":"Parce qu’un ange le lui avait ordonné"},"en":{"text":"Because an angel told her to"},"es":{"text":"Porque un ángel se lo mandó"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-006","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":18,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"O que deu Jónatas a David?","bible_ref":"1 Samuel 18:4","verse_text":"E Jônatas despiu a roupa que tinha sobre si, e deu-a a Davi, e outras roupas suas, até sua espada, e seu arco, e seu cinto."},"fr":{"prompt":"Que donna Jonathan à David ?","bible_ref":"1 Samuel 18:4","verse_text":"Il ôta le manteau qu’il portait, pour le donner à David; et il lui donna ses vêtements, même son épée, son arc et sa ceinture."},"en":{"prompt":"What did Jonathan give David?","bible_ref":"1 Samuel 18:4","verse_text":"And Jonathan stripped himself of the robe that was upon him, and gave it to David, and his garments, even to his sword, and to his bow, and to his girdle."},"es":{"prompt":"¿Qué le dio Jonathán a David?","bible_ref":"1 Samuel 18:4","verse_text":"Y Jonathán se desnudó la ropa que tenía sobre sí, y dióla á David, y otras ropas suyas, hasta su espada, y su arco, y su talabarte."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua roupa, a espada e o arco"},"fr":{"text":"Son manteau, son épée et son arc"},"en":{"text":"His robe, his sword and his bow"},"es":{"text":"Su ropa, su espada y su arco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um carro e cavalos"},"fr":{"text":"Un char et des chevaux"},"en":{"text":"A chariot and horses"},"es":{"text":"Un carro y caballos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma coroa de ouro"},"fr":{"text":"Une couronne d’or"},"en":{"text":"A crown of gold"},"es":{"text":"Una corona de oro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um anel e um selo"},"fr":{"text":"Une bague et un sceau"},"en":{"text":"A ring and a seal"},"es":{"text":"Un anillo y un sello"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-007","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":12,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Que profeta disse a David: «Tu és aquele homem»?","bible_ref":"2 Samuel 12:7","verse_text":"Então disse Natã a Davi: Tu és aquele homem. Assim disse o SENHOR, Deus de Israel: Eu te ungi por rei sobre Israel, e te livre da mão de Saul;"},"fr":{"prompt":"Quel prophète dit à David : « Tu es cet homme-là » ?","bible_ref":"2 Samuel 12:7","verse_text":"Et Nathan dit à David: Tu es cet homme-là! Ainsi parle l’Éternel, le Dieu d’Israël: Je t’ai oint pour roi sur Israël, et je t’ai délivré de la main de Saül;"},"en":{"prompt":"Which prophet said to David, “Thou art the man”?","bible_ref":"2 Samuel 12:7","verse_text":"And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;"},"es":{"prompt":"¿Qué profeta le dijo a David: «Tú eres aquel hombre»?","bible_ref":"2 Samuel 12:7","verse_text":"Entonces dijo Nathán á David: Tú eres aquel hombre. Así ha dicho Jehová, Dios de Israel: Yo te ungí por rey sobre Israel, y te libré de la mano de Saúl;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Natã"},"fr":{"text":"Nathan"},"en":{"text":"Nathan"},"es":{"text":"Nathán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gade"},"fr":{"text":"Gad"},"en":{"text":"Gad"},"es":{"text":"Gad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elijah"},"es":{"text":"Elías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-008","type":"choice","level":"medium","testament":"ot","book":"1KI","chapter":19,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"No monte, depois do vento, do terramoto e do fogo, o que ouviu Elias?","bible_ref":"1 Reis 19:12","verse_text":"E depois do terremoto um fogo: mas o SENHOR não estava no fogo. E depois do fogo uma voz agradável e suave."},"fr":{"prompt":"Sur la montagne, après le vent, le tremblement de terre et le feu, qu’entendit Élie ?","bible_ref":"1 Rois 19:12","verse_text":"Et après le tremblement de terre, un feu: l’Éternel n’était pas dans le feu. Et après le feu, un murmure doux et léger."},"en":{"prompt":"On the mountain, after the wind, the earthquake and the fire, what did Elijah hear?","bible_ref":"1 Kings 19:12","verse_text":"And after the earthquake a fire; but the LORD was not in the fire: and after the fire a still small voice."},"es":{"prompt":"En el monte, después del viento, el terremoto y el fuego, ¿qué oyó Elías?","bible_ref":"1 Reyes 19:12","verse_text":"Y tras el terremoto un fuego: mas Jehová no estaba en el fuego. Y tras el fuego un silbo apacible y delicado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma voz agradável e suave"},"fr":{"text":"Un murmure doux et léger"},"en":{"text":"A still small voice"},"es":{"text":"Un silbo apacible y delicado"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um trovão muito forte"},"fr":{"text":"Un très grand tonnerre"},"en":{"text":"A very loud thunder"},"es":{"text":"Un trueno muy fuerte"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma chuva forte"},"fr":{"text":"Une forte pluie"},"en":{"text":"A heavy rain"},"es":{"text":"Una lluvia fuerte"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O som de uma trombeta"},"fr":{"text":"Le son d’une trompette"},"en":{"text":"The sound of a trumpet"},"es":{"text":"El sonido de una trompeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-009","type":"choice","level":"medium","testament":"ot","book":"2KI","chapter":6,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Quando o SENHOR abriu os olhos ao servo de Eliseu, o que viu ele à volta do profeta?","bible_ref":"2 Reis 6:17","verse_text":"E orou Eliseu, e disse: Rogo-te, ó SENHOR, que abras seus olhos para que veja. Então o SENHOR abriu os olhos do jovem, e olhou; e eis que o monte estava cheio de cavaleiros, e de carros de fogo ao redor de Eliseu."},"fr":{"prompt":"Quand l’Éternel ouvrit les yeux du serviteur d’Élisée, que vit-il autour du prophète ?","bible_ref":"2 Rois 6:17","verse_text":"Élisée pria, et dit: Éternel, ouvre ses yeux, pour qu’il voie. Et l’Éternel ouvrit les yeux du serviteur, qui vit la montagne pleine de chevaux et de chars de feu autour d’Élisée."},"en":{"prompt":"When the LORD opened the eyes of Elisha’s young man, what did he see around the prophet?","bible_ref":"2 Kings 6:17","verse_text":"And Elisha prayed, and said, LORD, I pray thee, open his eyes, that he may see. And the LORD opened the eyes of the young man; and he saw: and, behold, the mountain was full of horses and chariots of fire round about Elisha."},"es":{"prompt":"Cuando Jehová abrió los ojos al criado de Eliseo, ¿qué vio alrededor del profeta?","bible_ref":"2 Reyes 6:17","verse_text":"Y oró Eliseo, y dijo: Ruégote, oh Jehová, que abras sus ojos para que vea. Entonces Jehová abrió los ojos del mozo, y miró: y he aquí que el monte estaba lleno de gente de á caballo, y de carros de fuego alrededor de Eliseo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cavaleiros e carros de fogo"},"fr":{"text":"Des chevaux et des chars de feu"},"en":{"text":"Horses and chariots of fire"},"es":{"text":"Jinetes y carros de fuego"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um muro de água"},"fr":{"text":"Un mur d’eau"},"en":{"text":"A wall of water"},"es":{"text":"Un muro de agua"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma nuvem escura"},"fr":{"text":"Une nuée sombre"},"en":{"text":"A dark cloud"},"es":{"text":"Una nube oscura"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Leões ferozes"},"fr":{"text":"Des lions féroces"},"en":{"text":"Fierce lions"},"es":{"text":"Leones feroces"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-010","type":"choice","level":"medium","testament":"ot","book":"EST","chapter":7,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Quem foi enforcado na forca que tinha sido preparada para Mardoqueu?","bible_ref":"Ester 7:10","verse_text":"Assim enforcaram a Hamã na forca que ele tinha mandado preparar para Mardoqueu; então o furor do rei se apaziguou."},"fr":{"prompt":"Qui fut pendu au bois préparé pour Mardochée ?","bible_ref":"Esther 7:10","verse_text":"Et l’on pendit Haman au bois qu’il avait préparé pour Mardochée. Et la colère du roi s’apaisa."},"en":{"prompt":"Who was hanged on the gallows that had been prepared for Mordecai?","bible_ref":"Esther 7:10","verse_text":"So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified."},"es":{"prompt":"¿Quién fue colgado en la horca que se había preparado para Mardochêo?","bible_ref":"Ester 7:10","verse_text":"Así colgaron á Amán en la horca que él había hecho aparejar para Mardochêo; y apaciguóse la ira del rey."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Hamã"},"fr":{"text":"Haman"},"en":{"text":"Haman"},"es":{"text":"Amán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Assuero"},"fr":{"text":"Assuérus"},"en":{"text":"Ahasuerus"},"es":{"text":"Assuero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Hegai"},"fr":{"text":"Hégaï"},"en":{"text":"Hegai"},"es":{"text":"Hegai"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mardoqueu"},"fr":{"text":"Mardochée"},"en":{"text":"Mordecai"},"es":{"text":"Mardochêo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-011","type":"choice","level":"medium","testament":"ot","book":"EZR","chapter":3,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"O que fizeram os velhos que tinham visto a primeira casa quando viram os alicerces da nova?","bible_ref":"Esdras 3:12","verse_text":"Porém muitos dos sacerdotes e dos levitas e dos chefes de famílias, já velhos, que haviam visto a primeira casa, quando viram a fundação desta casa, choravam em alta voz, mas muitos outros davam grandes gritos de alegria;"},"fr":{"prompt":"Que firent les vieillards qui avaient vu la première maison quand on posa les fondements de la nouvelle ?","bible_ref":"Esdras 3:12","verse_text":"Mais plusieurs des sacrificateurs et des Lévites, et des chefs de famille âgés, qui avaient vu la première maison, pleuraient à grand bruit pendant qu’on posait sous leurs yeux les fondements de cette maison. Beaucoup d’autres faisaient éclater leur joie par des cris,"},"en":{"prompt":"What did the old men who had seen the first house do when the foundation of the new one was laid?","bible_ref":"Ezra 3:12","verse_text":"But many of the priests and Levites and chief of the fathers, who were ancient men, that had seen the first house, when the foundation of this house was laid before their eyes, wept with a loud voice; and many shouted aloud for joy:"},"es":{"prompt":"¿Qué hicieron los ancianos que habían visto la primera casa cuando vieron los cimientos de la nueva?","bible_ref":"Esdras 3:12","verse_text":"Y muchos de los sacerdotes y de los Levitas y de los cabezas de los padres, ancianos que habían visto la casa primera, viendo fundar esta casa, lloraban en alta voz, mientras muchos otros daban grandes gritos de alegría."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Choraram em alta voz"},"fr":{"text":"Ils pleurèrent à grand bruit"},"en":{"text":"They wept with a loud voice"},"es":{"text":"Lloraron en alta voz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dançaram de alegria"},"fr":{"text":"Ils dansèrent de joie"},"en":{"text":"They danced for joy"},"es":{"text":"Danzaron de alegría"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ficaram em silêncio"},"fr":{"text":"Ils restèrent silencieux"},"en":{"text":"They kept silent"},"es":{"text":"Guardaron silencio"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rasgaram as vestes"},"fr":{"text":"Ils déchirèrent leurs vêtements"},"en":{"text":"They tore their clothes"},"es":{"text":"Rasgaron sus vestidos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-012","type":"choice","level":"medium","testament":"ot","book":"2CH","chapter":7,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Quando Salomão acabou de orar, desceu fogo do céu. O que consumiu esse fogo?","bible_ref":"2 Crónicas 7:1","verse_text":"E quando Salomão acabou de orar, o fogo desceu dos céus, e consumiu o holocausto e as vítimas; e a glória do SENHOR encheu a casa."},"fr":{"prompt":"Quand Salomon eut achevé de prier, le feu descendit du ciel. Que consuma ce feu ?","bible_ref":"2 Chroniques 7:1","verse_text":"Lorsque Salomon eut achevé de prier, le feu descendit du ciel et consuma l’holocauste et les sacrifices, et la gloire de l’Éternel remplit la maison."},"en":{"prompt":"When Solomon had made an end of praying, fire came down from heaven. What did it consume?","bible_ref":"2 Chronicles 7:1","verse_text":"Now when Solomon had made an end of praying, the fire came down from heaven, and consumed the burnt offering and the sacrifices; and the glory of the LORD filled the house."},"es":{"prompt":"Cuando Salomón acabó de orar, descendió fuego del cielo. ¿Qué consumió ese fuego?","bible_ref":"2 Crónicas 7:1","verse_text":"Y COMO Salomón acabó de orar, el fuego descendió de los cielos, y consumió el holocausto y las víctimas; y la gloria de Jehová hinchió la casa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O holocausto e as vítimas"},"fr":{"text":"L’holocauste et les sacrifices"},"en":{"text":"The burnt offering and the sacrifices"},"es":{"text":"El holocausto y las víctimas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"As portas do templo"},"fr":{"text":"Les portes du temple"},"en":{"text":"The doors of the temple"},"es":{"text":"Las puertas del templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O trono de Salomão"},"fr":{"text":"Le trône de Salomon"},"en":{"text":"Solomon’s throne"},"es":{"text":"El trono de Salomón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os ídolos da cidade"},"fr":{"text":"Les idoles de la ville"},"en":{"text":"The idols of the city"},"es":{"text":"Los ídolos de la ciudad"}}}]}$json$::jsonb);
