select public.upsert_bank_question($json${"id":"hist-medium-017","type":"verse","level":"medium","testament":"ot","book":"JOS","chapter":24,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses aos quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos _____ em cuja terra habitais: que eu e minha casa serviremos ao SENHOR.","bible_ref":"Josué 24:15","verse_text":"E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses aos quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos amorreus em cuja terra habitais: que eu e minha casa serviremos ao SENHOR."},"fr":{"prompt":"Et si vous ne trouvez pas bon de servir l’Éternel, choisissez aujourd’hui qui vous voulez servir, ou les dieux que servaient vos pères au-delà du fleuve, ou les dieux des _____ dans le pays desquels vous habitez. Moi et ma maison, nous servirons l’Éternel.","bible_ref":"Josué 24:15","verse_text":"Et si vous ne trouvez pas bon de servir l’Éternel, choisissez aujourd’hui qui vous voulez servir, ou les dieux que servaient vos pères au-delà du fleuve, ou les dieux des Amoréens dans le pays desquels vous habitez. Moi et ma maison, nous servirons l’Éternel."},"en":{"prompt":"And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the _____, in whose land ye dwell: but as for me and my house, we will serve the LORD.","bible_ref":"Joshua 24:15","verse_text":"And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."},"es":{"prompt":"Y si mal os parece servir á Jehová, escogeos hoy á quién sirváis; si á los dioses á quienes sirvieron vuestros padres, cuando estuvieron de esotra parte del río, ó á los dioses de los _____ en cuya tierra habitáis: que yo y mi casa serviremos á Jehová.","bible_ref":"Josué 24:15","verse_text":"Y si mal os parece servir á Jehová, escogeos hoy á quién sirváis; si á los dioses á quienes sirvieron vuestros padres, cuando estuvieron de esotra parte del río, ó á los dioses de los Amorrheos en cuya tierra habitáis: que yo y mi casa serviremos á Jehová."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"egípcios"},"fr":{"text":"Égyptiens"},"en":{"text":"Egyptians"},"es":{"text":"Egipcios"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"amorreus"},"fr":{"text":"Amoréens"},"en":{"text":"Amorites"},"es":{"text":"Amorrheos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"moabitas"},"fr":{"text":"Moabites"},"en":{"text":"Moabites"},"es":{"text":"Moabitas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"filisteus"},"fr":{"text":"Philistins"},"en":{"text":"Philistines"},"es":{"text":"Filisteos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-018","type":"verse","level":"medium","testament":"ot","book":"1SA","chapter":15,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"E Samuel disse: Tem o SENHOR tanto contentamento com os holocaustos e vítimas, como em obedecer às palavras do SENHOR? Certamente o obedecer é melhor que os sacrifícios; e o prestar atenção que a gordura dos _____:","bible_ref":"1 Samuel 15:22","verse_text":"E Samuel disse: Tem o SENHOR tanto contentamento com os holocaustos e vítimas, como em obedecer às palavras do SENHOR? Certamente o obedecer é melhor que os sacrifícios; e o prestar atenção que a gordura dos carneiros:"},"fr":{"prompt":"Samuel dit: L’Éternel trouve-t-il du plaisir dans les holocaustes et les sacrifices, comme dans l’obéissance à la voix de l’Éternel? Voici, l’obéissance vaut mieux que les sacrifices, et l’observation de sa parole vaut mieux que la graisse des _____.","bible_ref":"1 Samuel 15:22","verse_text":"Samuel dit: L’Éternel trouve-t-il du plaisir dans les holocaustes et les sacrifices, comme dans l’obéissance à la voix de l’Éternel? Voici, l’obéissance vaut mieux que les sacrifices, et l’observation de sa parole vaut mieux que la graisse des béliers."},"en":{"prompt":"And Samuel said, Hath the LORD as great delight in burnt offerings and sacrifices, as in obeying the voice of the LORD? Behold, to obey is better than sacrifice, and to hearken than the fat of _____.","bible_ref":"1 Samuel 15:22","verse_text":"And Samuel said, Hath the LORD as great delight in burnt offerings and sacrifices, as in obeying the voice of the LORD? Behold, to obey is better than sacrifice, and to hearken than the fat of rams."},"es":{"prompt":"Y Samuel dijo: ¿Tiene Jehová tanto contentamiento con los holocaustos y víctimas, como en obedecer á las palabras de Jehová? Ciertamente el obedecer es mejor que los sacrificios; y el prestar atención que el sebo de los _____:","bible_ref":"1 Samuel 15:22","verse_text":"Y Samuel dijo: ¿Tiene Jehová tanto contentamiento con los holocaustos y víctimas, como en obedecer á las palabras de Jehová? Ciertamente el obedecer es mejor que los sacrificios; y el prestar atención que el sebo de los carneros:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"carneiros"},"fr":{"text":"béliers"},"en":{"text":"rams"},"es":{"text":"carneros"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"bois"},"fr":{"text":"bœufs"},"en":{"text":"oxen"},"es":{"text":"bueyes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"cordeiros"},"fr":{"text":"agneaux"},"en":{"text":"lambs"},"es":{"text":"corderos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"bodes"},"fr":{"text":"boucs"},"en":{"text":"goats"},"es":{"text":"machos cabríos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-019","type":"verse","level":"medium","testament":"ot","book":"1KI","chapter":18,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"E aproximando-se Elias a todo o povo, disse: Até quando hesitareis vós entre dois pensamentos? Se o SENHOR é Deus, segui-lhe; e se _____, ide depois dele. E o povo não respondeu palavra.","bible_ref":"1 Reis 18:21","verse_text":"E aproximando-se Elias a todo o povo, disse: Até quando hesitareis vós entre dois pensamentos? Se o SENHOR é Deus, segui-lhe; e se Baal, ide depois dele. E o povo não respondeu palavra."},"fr":{"prompt":"Alors Élie s’approcha de tout le peuple, et dit: Jusqu’à quand clocherez-vous des deux côtés? Si l’Éternel est Dieu, allez après lui; si c’est _____, allez après lui! Le peuple ne lui répondit rien.","bible_ref":"1 Rois 18:21","verse_text":"Alors Élie s’approcha de tout le peuple, et dit: Jusqu’à quand clocherez-vous des deux côtés? Si l’Éternel est Dieu, allez après lui; si c’est Baal, allez après lui! Le peuple ne lui répondit rien."},"en":{"prompt":"And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if _____, then follow him. And the people answered him not a word.","bible_ref":"1 Kings 18:21","verse_text":"And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word."},"es":{"prompt":"Y acercándose Elías á todo el pueblo, dijo: ¿Hasta cuándo claudicaréis vosotros entre dos pensamientos? Si Jehová es Dios, seguidle; y si _____, id en pos de él. Y el pueblo no respondió palabra.","bible_ref":"1 Reyes 18:21","verse_text":"Y acercándose Elías á todo el pueblo, dijo: ¿Hasta cuándo claudicaréis vosotros entre dos pensamientos? Si Jehová es Dios, seguidle; y si Baal, id en pos de él. Y el pueblo no respondió palabra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Baal"},"fr":{"text":"Baal"},"en":{"text":"Baal"},"es":{"text":"Baal"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dagom"},"fr":{"text":"Dagon"},"en":{"text":"Dagon"},"es":{"text":"Dagón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quemos"},"fr":{"text":"Kemosch"},"en":{"text":"Chemosh"},"es":{"text":"Chêmos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moloque"},"fr":{"text":"Moloc"},"en":{"text":"Molech"},"es":{"text":"Moloch"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-medium-020","type":"verse","level":"medium","testament":"ot","book":"NEH","chapter":8,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa _____.","bible_ref":"Neemias 8:10","verse_text":"E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa força."},"fr":{"prompt":"Ils leur dirent: Allez, mangez des viandes grasses et buvez des liqueurs douces, et envoyez des portions à ceux qui n’ont rien de préparé, car ce jour est consacré à notre Seigneur; ne vous affligez pas, car la joie de l’Éternel sera votre _____.","bible_ref":"Néhémie 8:10","verse_text":"Ils leur dirent: Allez, mangez des viandes grasses et buvez des liqueurs douces, et envoyez des portions à ceux qui n’ont rien de préparé, car ce jour est consacré à notre Seigneur; ne vous affligez pas, car la joie de l’Éternel sera votre force."},"en":{"prompt":"Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your _____.","bible_ref":"Nehemiah 8:10","verse_text":"Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength."},"es":{"prompt":"Díjoles luego: Id, comed grosuras, y bebed vino dulce, y enviad porciones á los que no tienen prevenido; porque día santo es á nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra _____.","bible_ref":"Nehemías 8:10","verse_text":"Díjoles luego: Id, comed grosuras, y bebed vino dulce, y enviad porciones á los que no tienen prevenido; porque día santo es á nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra fortaleza."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"canção"},"fr":{"text":"chant"},"en":{"text":"song"},"es":{"text":"canción"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"força"},"fr":{"text":"force"},"en":{"text":"strength"},"es":{"text":"fortaleza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"paz"},"fr":{"text":"paix"},"en":{"text":"peace"},"es":{"text":"paz"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"luz"},"fr":{"text":"lumière"},"en":{"text":"light"},"es":{"text":"luz"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-001","type":"choice","level":"hard","testament":"ot","book":"JOS","chapter":10,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Josué 10:13, em que livro estava escrito que o sol se deteve?","bible_ref":"Josué 10:13","verse_text":"E o sol se deteve e a lua se parou, Até tanto que a gente se havia vingado de seus inimigos. Não está este escrito no livro de Jasar? E o sol se parou em meio do céu, e não se apressou a se pôr quase um dia inteiro."},"fr":{"prompt":"Selon Josué 10:13, dans quel livre était-il écrit que le soleil s’arrêta ?","bible_ref":"Josué 10:13","verse_text":"Et le soleil s’arrêta, et la lune suspendit sa course, Jusqu’à ce que la nation eût tiré vengeance de ses ennemis. Cela n’est-il pas écrit dans le livre du Juste? Le soleil s’arrêta au milieu du ciel, et ne se hâta point de se coucher, presque tout un jour."},"en":{"prompt":"According to Joshua 10:13, in which book was it written that the sun stood still?","bible_ref":"Joshua 10:13","verse_text":"And the sun stood still, and the moon stayed, until the people had avenged themselves upon their enemies. Is not this written in the book of Jasher? So the sun stood still in the midst of heaven, and hasted not to go down about a whole day."},"es":{"prompt":"Según Josué 10:13, ¿en qué libro estaba escrito que el sol se detuvo?","bible_ref":"Josué 10:13","verse_text":"Y el sol se detuvo y la luna se paró, hasta tanto que la gente se hubo vengado de sus enemigos. ¿No está aquesto escrito en el libro de Jasher? Y el sol se paró en medio del cielo, y no se apresuró á ponerse casi un día entero."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No livro de Jasar"},"fr":{"text":"Dans le livre du Juste"},"en":{"text":"In the book of Jasher"},"es":{"text":"En el libro de Jasher"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No livro das Guerras do SENHOR"},"fr":{"text":"Dans le livre des guerres de l’Éternel"},"en":{"text":"In the book of the wars of the LORD"},"es":{"text":"En el libro de las batallas de Jehová"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No livro da Lei"},"fr":{"text":"Dans le livre de la loi"},"en":{"text":"In the book of the law"},"es":{"text":"En el libro de la ley"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nas crónicas dos reis de Israel"},"fr":{"text":"Dans les chroniques des rois d’Israël"},"en":{"text":"In the chronicles of the kings of Israel"},"es":{"text":"En las crónicas de los reyes de Israel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-002","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":11,"verse_start":34,"verse_end":34,"texts":{"pt":{"prompt":"Quando o juiz Jefté voltou a sua casa, em Mispá, quem lhe saiu ao encontro com adufes e danças?","bible_ref":"Juízes 11:34","verse_text":"E voltando Jefté a Mispá à sua casa, eis que sua filha lhe saiu a receber com adufes e danças, e era a única, a única sua; não tinha além dela outro filho nem filha."},"fr":{"prompt":"Quand le juge Jephthé revint dans sa maison à Mitspa, qui sortit au-devant de lui avec des tambourins et des danses ?","bible_ref":"Juges 11:34","verse_text":"Jephthé retourna dans sa maison à Mitspa. Et voici, sa fille sortit au-devant de lui avec des tambourins et des danses. C’était son unique enfant; il n’avait point de fils et point d’autre fille."},"en":{"prompt":"When the judge Jephthah came home to Mizpeh, who came out to meet him with timbrels and dances?","bible_ref":"Judges 11:34","verse_text":"And Jephthah came to Mizpeh unto his house, and, behold, his daughter came out to meet him with timbrels and with dances: and she was his only child; beside her he had neither son nor daughter."},"es":{"prompt":"Cuando el juez Jephté volvió a su casa en Mizpa, ¿quién le salió a recibir con adufes y danzas?","bible_ref":"Jueces 11:34","verse_text":"Y volviendo Jephté á Mizpa á su casa, he aquí que su hija le salió á recibir con adufes y danzas, y era la sola, la única suya; no tenía fuera de ella otro hijo ni hija."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua filha única"},"fr":{"text":"Sa fille unique"},"en":{"text":"His only daughter"},"es":{"text":"Su hija única"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu filho mais velho"},"fr":{"text":"Son fils aîné"},"en":{"text":"His eldest son"},"es":{"text":"Su hijo mayor"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A sua mulher"},"fr":{"text":"Sa femme"},"en":{"text":"His wife"},"es":{"text":"Su mujer"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um dos seus servos"},"fr":{"text":"Un de ses serviteurs"},"en":{"text":"One of his servants"},"es":{"text":"Uno de sus siervos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-003","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":12,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Os homens de Gileade mandavam dizer «Chibolete». Quem não conseguia pronunciar bem a palavra?","bible_ref":"Juízes 12:6","verse_text":"Então lhe diziam: Agora, pois, dize, Chibolete. E ele dizia, Sibolete; porque não podia pronunciar daquela sorte. Então lhe lançavam mão, e lhe degolavam junto aos vaus do Jordão. E morreram então dos de Efraim quarenta e dois mil."},"fr":{"prompt":"Les hommes de Galaad faisaient dire « Schibboleth ». Qui ne pouvait pas bien prononcer ce mot ?","bible_ref":"Juges 12:6","verse_text":"Ils lui disaient alors: Hé bien, dis Schibboleth. Et il disait Sibboleth, car il ne pouvait pas bien prononcer. Sur quoi les hommes de Galaad le saisissaient, et l’égorgeaient près des gués du Jourdain. Il périt en ce temps-là quarante-deux mille hommes d’Éphraïm."},"en":{"prompt":"The men of Gilead made men say “Shibboleth”. Who could not pronounce it right?","bible_ref":"Judges 12:6","verse_text":"Then said they unto him, Say now Shibboleth: and he said Sibboleth: for he could not frame to pronounce it right. Then they took him, and slew him at the passages of Jordan: and there fell at that time of the Ephraimites forty and two thousand."},"es":{"prompt":"Los hombres de Galaad hacían decir «Shiboleth». ¿Quiénes no podían pronunciarlo bien?","bible_ref":"Jueces 12:6","verse_text":"Entonces le decían: Ahora pues, di, Shiboleth. Y él decía, Siboleth; porque no podía pronunciar de aquella suerte. Entonces le echaban mano, y le degollaban junto á los vados del Jordán. Y murieron entonces de los de Ephraim cuarenta y dos mil."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os efraimitas"},"fr":{"text":"Les hommes d’Éphraïm"},"en":{"text":"The Ephraimites"},"es":{"text":"Los de Ephraim"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os benjamitas"},"fr":{"text":"Les Benjamites"},"en":{"text":"The Benjamites"},"es":{"text":"Los benjamitas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os amonitas"},"fr":{"text":"Les Ammonites"},"en":{"text":"The Ammonites"},"es":{"text":"Los amonitas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os filisteus"},"fr":{"text":"Les Philistins"},"en":{"text":"The Philistines"},"es":{"text":"Los filisteos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-004","type":"choice","level":"hard","testament":"ot","book":"RUT","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Como se chamavam os dois filhos de Elimeleque e Noemi?","bible_ref":"Rute 1:2","verse_text":"O nome daquele homem era Elimeleque, e o de sua mulher Noemi; e os nomes de seus dois filhos eram Malom e Quiliom, efrateus de Belém de Judá. Chegaram, pois, aos campos de Moabe, e assentaram ali."},"fr":{"prompt":"Comment s’appelaient les deux fils d’Élimélec et de Naomi ?","bible_ref":"Ruth 1:2","verse_text":"Le nom de cet homme était Élimélec, celui de sa femme Naomi, et ses deux fils s’appelaient Machlon et Kiljon; ils étaient Éphratiens, de Bethléhem de Juda. Arrivés au pays de Moab, ils y fixèrent leur demeure."},"en":{"prompt":"What were the names of the two sons of Elimelech and Naomi?","bible_ref":"Ruth 1:2","verse_text":"And the name of the man was Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Beth-lehem-judah. And they came into the country of Moab, and continued there."},"es":{"prompt":"¿Cómo se llamaban los dos hijos de Elimelech y Noemi?","bible_ref":"Rut 1:2","verse_text":"El nombre de aquel varón era Elimelech, y el de su mujer Noemi; y los nombres de sus dos hijos eran, Mahalón y Chelión, Ephrateos de Beth-lehem de Judá. Llegaron pues á los campos de Moab, y asentaron allí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Malom e Quiliom"},"fr":{"text":"Machlon et Kiljon"},"en":{"text":"Mahlon and Chilion"},"es":{"text":"Mahalón y Chelión"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quis e Ner"},"fr":{"text":"Kis et Ner"},"en":{"text":"Kish and Ner"},"es":{"text":"Cis y Ner"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Joel e Abias"},"fr":{"text":"Joël et Abija"},"en":{"text":"Joel and Abiah"},"es":{"text":"Joel y Abia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Hofni e Fineias"},"fr":{"text":"Hophni et Phinées"},"en":{"text":"Hophni and Phinehas"},"es":{"text":"Ophni y Phinees"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-005","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":4,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Quais eram os dois filhos de Eli que morreram quando a arca de Deus foi tomada?","bible_ref":"1 Samuel 4:11","verse_text":"E a arca de Deus foi tomada, e morreram os dois filhos de Eli, Hofni e Fineias."},"fr":{"prompt":"Quels étaient les deux fils d’Éli qui moururent quand l’arche de Dieu fut prise ?","bible_ref":"1 Samuel 4:11","verse_text":"L’arche de Dieu fut prise, et les deux fils d’Éli, Hophni et Phinées, moururent."},"en":{"prompt":"Who were the two sons of Eli slain when the ark of God was taken?","bible_ref":"1 Samuel 4:11","verse_text":"And the ark of God was taken; and the two sons of Eli, Hophni and Phinehas, were slain."},"es":{"prompt":"¿Quiénes eran los dos hijos de Elí que murieron cuando el arca de Dios fue tomada?","bible_ref":"1 Samuel 4:11","verse_text":"Y el arca de Dios fué tomada, y muertos los dos hijos de Eli, Ophni y Phinees."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Hofni e Fineias"},"fr":{"text":"Hophni et Phinées"},"en":{"text":"Hophni and Phinehas"},"es":{"text":"Ophni y Phinees"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nadabe e Abiú"},"fr":{"text":"Nadab et Abihu"},"en":{"text":"Nadab and Abihu"},"es":{"text":"Nadab y Abiú"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Joel e Abias"},"fr":{"text":"Joël et Abija"},"en":{"text":"Joel and Abiah"},"es":{"text":"Joel y Abia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Eleazar e Itamar"},"fr":{"text":"Éléazar et Ithamar"},"en":{"text":"Eleazar and Ithamar"},"es":{"text":"Eleazar e Ithamar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-006","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":14,"verse_start":51,"verse_end":51,"texts":{"pt":{"prompt":"Como se chamava o pai do rei Saul?","bible_ref":"1 Samuel 14:51","verse_text":"Porque Quis pai de Saul, e Ner pai de Abner, foram filhos de Abiel."},"fr":{"prompt":"Comment s’appelait le père du roi Saül ?","bible_ref":"1 Samuel 14:51","verse_text":"Kis, père de Saül, et Ner, père d’Abner, étaient fils d’Abiel."},"en":{"prompt":"What was the name of King Saul’s father?","bible_ref":"1 Samuel 14:51","verse_text":"And Kish was the father of Saul; and Ner the father of Abner was the son of Abiel."},"es":{"prompt":"¿Cómo se llamaba el padre del rey Saúl?","bible_ref":"1 Samuel 14:51","verse_text":"Porque Cis padre de Saúl, y Ner padre de Abner, fueron hijos de Abiel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quis"},"fr":{"text":"Kis"},"en":{"text":"Kish"},"es":{"text":"Cis"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ner"},"fr":{"text":"Ner"},"en":{"text":"Ner"},"es":{"text":"Ner"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jessé"},"fr":{"text":"Isaï"},"en":{"text":"Jesse"},"es":{"text":"Isaí"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Elcana"},"fr":{"text":"Elkana"},"en":{"text":"Elkanah"},"es":{"text":"Elcana"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-007","type":"choice","level":"hard","testament":"ot","book":"2SA","chapter":9,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Que filho de Jónatas se prostrou diante de David e lhe disse: «Eis aqui o teu servo»?","bible_ref":"2 Samuel 9:6","verse_text":"E vindo Mefibosete, filho de Jônatas filho de Saul, a Davi, prostrou-se sobre seu rosto, e fez reverência. E disse Davi: Mefibosete. E ele respondeu: Eis aqui teu servo."},"fr":{"prompt":"Quel fils de Jonathan se prosterna devant David et lui dit : « Voici ton serviteur » ?","bible_ref":"2 Samuel 9:6","verse_text":"Et Mephiboscheth, fils de Jonathan, fils de Saül, vint auprès de David, tomba sur sa face et se prosterna. David dit: Mephiboscheth! Et il répondit: Voici ton serviteur."},"en":{"prompt":"Which son of Jonathan fell on his face before David and said, “Behold thy servant”?","bible_ref":"2 Samuel 9:6","verse_text":"Now when Mephibosheth, the son of Jonathan, the son of Saul, was come unto David, he fell on his face, and did reverence. And David said, Mephibosheth. And he answered, Behold thy servant!"},"es":{"prompt":"¿Qué hijo de Jonathán se postró ante David y le dijo: «He aquí tu siervo»?","bible_ref":"2 Samuel 9:6","verse_text":"Y venido Mephi-boseth, hijo de Jonathán hijo de Saúl, á David, postróse sobre su rostro, é hizo reverencia. Y dijo David: Mephi-boseth. Y él respondió: He aquí tu siervo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mefibosete"},"fr":{"text":"Mephiboscheth"},"en":{"text":"Mephibosheth"},"es":{"text":"Mephi-boseth"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Is-Bosete"},"fr":{"text":"Isch-Boscheth"},"en":{"text":"Ish-bosheth"},"es":{"text":"Is-boseth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Absalão"},"fr":{"text":"Absalom"},"en":{"text":"Absalom"},"es":{"text":"Absalom"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Amnom"},"fr":{"text":"Amnon"},"en":{"text":"Amnon"},"es":{"text":"Amnón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-008","type":"choice","level":"hard","testament":"ot","book":"1KI","chapter":12,"verse_start":28,"verse_end":29,"texts":{"pt":{"prompt":"Em 1 Reis 12, o rei fez dois bezerros de ouro. Em que cidades os pôs?","bible_ref":"1 Reis 12:28-29","verse_text":"E havido conselho, fez o rei dois bezerros de ouro, e disse ao povo: Demais subistes a Jerusalém: eis que teus deuses, ó Israel, que te fizeram subir da terra do Egito. E pôs o um em Betel, e o outro pôs em Dã."},"fr":{"prompt":"En 1 Rois 12, le roi fit deux veaux d’or. Dans quelles villes les plaça-t-il ?","bible_ref":"1 Rois 12:28-29","verse_text":"Après s’être consulté, le roi fit deux veaux d’or, et il dit au peuple: Assez longtemps vous êtes montés à Jérusalem; Israël! voici ton Dieu, qui t’a fait sortir du pays d’Égypte. Il plaça l’un de ces veaux à Béthel, et il mit l’autre à Dan."},"en":{"prompt":"In 1 Kings 12, the king made two calves of gold. In which cities did he set them?","bible_ref":"1 Kings 12:28-29","verse_text":"Whereupon the king took counsel, and made two calves of gold, and said unto them, It is too much for you to go up to Jerusalem: behold thy gods, O Israel, which brought thee up out of the land of Egypt. And he set the one in Beth-el, and the other put he in Dan."},"es":{"prompt":"En 1 Reyes 12, el rey hizo dos becerros de oro. ¿En qué ciudades los puso?","bible_ref":"1 Reyes 12:28-29","verse_text":"Y habido consejo, hizo el rey dos becerros de oro, y dijo al pueblo: Harto habéis subido á Jerusalem: he aquí tus dioses, oh Israel, que te hicieron subir de la tierra de Egipto. Y puso el uno en Beth-el, y el otro puso en Dan."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Betel e Dã"},"fr":{"text":"Béthel et Dan"},"en":{"text":"Beth-el and Dan"},"es":{"text":"Beth-el y Dan"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Siquém e Samaria"},"fr":{"text":"Sichem et Samarie"},"en":{"text":"Shechem and Samaria"},"es":{"text":"Sichêm y Samaria"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Gilgal e Siló"},"fr":{"text":"Guilgal et Silo"},"en":{"text":"Gilgal and Shiloh"},"es":{"text":"Gilgal y Silo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Hebrom e Berseba"},"fr":{"text":"Hébron et Beer-Schéba"},"en":{"text":"Hebron and Beer-sheba"},"es":{"text":"Hebrón y Beer-seba"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-009","type":"choice","level":"hard","testament":"ot","book":"2KI","chapter":20,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Em 2 Reis 20, quantos degraus voltou atrás a sombra no relógio de Acaz?","bible_ref":"2 Reis 20:11","verse_text":"Então o profeta Isaías clamou ao SENHOR; e fez voltar a sombra pelos degraus que havia descido no relógio de Acaz, dez degraus atrás."},"fr":{"prompt":"En 2 Rois 20, de combien de degrés l’ombre recula-t-elle sur les degrés d’Achaz ?","bible_ref":"2 Rois 20:11","verse_text":"Alors Ésaïe, le prophète, invoqua l’Éternel, qui fit reculer l’ombre de dix degrés sur les degrés d’Achaz, où elle était descendue."},"en":{"prompt":"In 2 Kings 20, how many degrees did the shadow go back on the dial of Ahaz?","bible_ref":"2 Kings 20:11","verse_text":"And Isaiah the prophet cried unto the LORD: and he brought the shadow ten degrees backward, by which it had gone down in the dial of Ahaz."},"es":{"prompt":"En 2 Reyes 20, ¿cuántos grados volvió atrás la sombra en el reloj de Achâz?","bible_ref":"2 Reyes 20:11","verse_text":"Entonces el profeta Isaías clamó á Jehová; é hizo volver la sombra por los grados que había descendido en el reloj de Achâz, diez grados atrás."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"10 degraus"},"fr":{"text":"10 degrés"},"en":{"text":"10 degrees"},"es":{"text":"10 grados"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"5 degraus"},"fr":{"text":"5 degrés"},"en":{"text":"5 degrees"},"es":{"text":"5 grados"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"15 degraus"},"fr":{"text":"15 degrés"},"en":{"text":"15 degrees"},"es":{"text":"15 grados"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"7 degraus"},"fr":{"text":"7 degrés"},"en":{"text":"7 degrees"},"es":{"text":"7 grados"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-010","type":"choice","level":"hard","testament":"ot","book":"1CH","chapter":4,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Quem pediu a Deus: «Abençoa-me muito e alarga os meus limites», e foi atendido?","bible_ref":"1 Crónicas 4:10","verse_text":"Mas Jabez invocou ao Deus de Israel, dizendo: Ah, se tu me abençoares muito, e ampliares os meus limites, e se tua mão for comigo, e me protegeres do mal, para que eu não sofra! E Deus fez suceder o que ele havia pedido."},"fr":{"prompt":"Qui demanda à Dieu : « Bénis-moi et étends mes limites », et fut exaucé ?","bible_ref":"1 Chroniques 4:10","verse_text":"Jaebets invoqua le Dieu d’Israël, en disant: Si tu me bénis et que tu étendes mes limites, si ta main est avec moi, et si tu me préserves du malheur, en sorte que je ne sois pas dans la souffrance!… Et Dieu accorda ce qu’il avait demandé."},"en":{"prompt":"Who called on God, “Bless me indeed, and enlarge my coast”, and was granted it?","bible_ref":"1 Chronicles 4:10","verse_text":"And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil, that it may not grieve me! And God granted him that which he requested."},"es":{"prompt":"¿Quién pidió a Dios: «Bendíceme y ensancha mi territorio», y le fue concedido?","bible_ref":"1 Crónicas 4:10","verse_text":"E invocó Jabes al Dios de Israel, diciendo: ¡Oh si me dieras bendición, y ensancharas mi término, y si tu mano fuera conmigo, y me libraras de mal, que no me dañe! E hizo Dios que le viniese lo que pidió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jabez"},"fr":{"text":"Jaebets"},"en":{"text":"Jabez"},"es":{"text":"Jabes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Obede-Edom"},"fr":{"text":"Obed-Édom"},"en":{"text":"Obed-edom"},"es":{"text":"Obed-edom"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Asafe"},"fr":{"text":"Asaph"},"en":{"text":"Asaph"},"es":{"text":"Asaph"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Hemã"},"fr":{"text":"Héman"},"en":{"text":"Heman"},"es":{"text":"Hemán"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-011","type":"choice","level":"hard","testament":"ot","book":"NEH","chapter":1,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Que função tinha Neemias ao serviço do rei?","bible_ref":"Neemias 1:11","verse_text":"Por favor, SENHOR, estejam teus ouvidos atentos à oração do teu servo, e a oração de teus servos, que desejam temer o teu nome; e, por favor, faze ter sucesso hoje a teu servo, e dá-lhe favor diante deste homem! Pois eu era copeiro do rei."},"fr":{"prompt":"Quelle charge Néhémie avait-il au service du roi ?","bible_ref":"Néhémie 1:11","verse_text":"Ah! Seigneur, que ton oreille soit attentive à la prière de ton serviteur, et à la prière de tes serviteurs qui veulent craindre ton nom! Donne aujourd’hui du succès à ton serviteur, et fais-lui trouver grâce devant cet homme! J’étais alors échanson du roi."},"en":{"prompt":"What was Nehemiah’s office in the king’s service?","bible_ref":"Nehemiah 1:11","verse_text":"O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."},"es":{"prompt":"¿Qué oficio tenía Nehemías al servicio del rey?","bible_ref":"Nehemías 1:11","verse_text":"Ruégote, oh Jehová, esté ahora atento tu oído á la oración de tu siervo, y á la oración de tus siervos, quienes desean temer tu nombre: y ahora concede hoy próspero suceso á tu siervo, y dale gracia delante de aquel varón. Porque yo servía de copero al rey."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Copeiro"},"fr":{"text":"Échanson"},"en":{"text":"Cupbearer"},"es":{"text":"Copero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Padeiro"},"fr":{"text":"Panetier"},"en":{"text":"Baker"},"es":{"text":"Panadero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Escriba"},"fr":{"text":"Scribe"},"en":{"text":"Scribe"},"es":{"text":"Escriba"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Porteiro"},"fr":{"text":"Portier"},"en":{"text":"Porter"},"es":{"text":"Portero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist-hard-012","type":"choice","level":"hard","testament":"ot","book":"EST","chapter":3,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Em Ester 3:7, o que quer dizer «Pur», lançado diante de Hamã?","bible_ref":"Ester 3:7","verse_text":"No primeiro mês (que é o mês de Nisã), no décimo segundo ano do rei Assuero, foi lançada Pur, isto é, a sorte, diante de Hamã, para cada dia e para cada mês; e a sorte indicou o décimo segundo mês, o mês de Adar."},"fr":{"prompt":"En Esther 3:7, que signifie le « pur » jeté devant Haman ?","bible_ref":"Esther 3:7","verse_text":"Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on jeta le pur, c’est-à-dire le sort, devant Haman, pour chaque jour et pour chaque mois, jusqu’au douzième mois, qui est le mois d’Adar."},"en":{"prompt":"In Esther 3:7, what does “Pur”, cast before Haman, mean?","bible_ref":"Esther 3:7","verse_text":"In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar."},"es":{"prompt":"En Esther 3:7, ¿qué significa «Pur», echado delante de Amán?","bible_ref":"Ester 3:7","verse_text":"En el mes primero, que es el mes de Nisán, en el año duodécimo del rey Assuero, fué echada Pur, esto es, la suerte, delante de Amán, de día en día y de mes en mes; y salió el mes duodécimo, que es el mes de Adar."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sorte"},"fr":{"text":"Le sort"},"en":{"text":"The lot"},"es":{"text":"La suerte"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O jejum"},"fr":{"text":"Le jeûne"},"en":{"text":"The fast"},"es":{"text":"El ayuno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O decreto"},"fr":{"text":"Le décret"},"en":{"text":"The decree"},"es":{"text":"El decreto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A festa"},"fr":{"text":"La fête"},"en":{"text":"The feast"},"es":{"text":"La fiesta"}}}]}$json$::jsonb);
