contra ti."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"profetas"},"fr":{"text":"prophètes"},"en":{"text":"prophets"},"es":{"text":"profetas"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"olhos"},"fr":{"text":"regards"},"en":{"text":"eyes"},"es":{"text":"ojos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"servos"},"fr":{"text":"serviteurs"},"en":{"text":"servants"},"es":{"text":"siervos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"anjos"},"fr":{"text":"anges"},"en":{"text":"angels"},"es":{"text":"ángeles"}}}]}$json$::jsonb);
