select public.upsert_bank_question($json${"id":"hist-hard-020","type":"verse","level":"hard","testament":"ot","book":"1KI","chapter":8,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"Mas, na verdade, haveria Deus de habitar na terra? Eis que os céus, e até o céu dos céus, não te podem _____; quanto menos esta casa que eu edifiquei!","bible_ref":"1 Reis 8:27","verse_text":"Mas, na verdade, haveria Deus de habitar na terra? Eis que os céus, e até o céu dos céus, não te podem conter; quanto menos esta casa que eu edifiquei!"},"fr":{"prompt":"Mais quoi! Dieu habiterait-il véritablement sur la terre? Voici, les cieux et les cieux des cieux ne peuvent te _____: combien moins cette maison que je t’ai bâtie!","bible_ref":"1 Rois 8:27","verse_text":"Mais quoi! Dieu habiterait-il véritablement sur la terre? Voici, les cieux et les cieux des cieux ne peuvent te contenir: combien moins cette maison que je t’ai bâtie!"},"en":{"prompt":"But will God indeed dwell on the earth? behold, the heaven and heaven of heavens cannot _____ thee; how much less this house that I have builded?","bible_ref":"1 Kings 8:27","verse_text":"But will God indeed dwell on the earth? behold, the heaven and heaven of heavens cannot contain thee; how much less this house that I have builded?"},"es":{"prompt":"Empero ¿es verdad que Dios haya de morar sobre la tierra? He aquí que los cielos, los cielos de los cielos, no te pueden _____: ¿cuánto menos esta casa que yo he edificado?","bible_ref":"1 Reyes 8:27","verse_text":"Empero ¿es verdad que Dios haya de morar sobre la tierra? He aquí que los cielos, los cielos de los cielos, no te pueden contener: ¿cuánto menos esta casa que yo he edificado?"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"esconder"},"fr":{"text":"cacher"},"en":{"text":"hide"},"es":{"text":"esconder"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"conter"},"fr":{"text":"contenir"},"en":{"text":"contain"},"es":{"text":"contener"}}},{"position":3,"is